import React, { useState } from 'react';
import { useQuery, useMutation } from '@apollo/client';
import { 
  Box, 
  Typography, 
  Button, 
  Paper, 
  Grid, 
  Snackbar, 
  Alert,
  useTheme,
  useMediaQuery
} from '@mui/material';
import { 
  Add as AddIcon,
  CalendarMonth as CalendarIcon,
  People as PeopleIcon,
  TrendingUp as TrendingUpIcon
} from '@mui/icons-material';
import { useNavigate, Outlet } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { 
  GET_ALL_APPOINTMENTS, 
  GET_ALL_CONTACTS, 
  CREATE_APPOINTMENT, 
  UPDATE_APPOINTMENT, 
  DELETE_APPOINTMENT, 
  UPDATE_APPOINTMENT_STATUS, 
  UPDATE_CONTACT_STATUS 
} from '../../graphql/admin';
import AppointmentForm from './AppointmentForm';
import ConfirmationDialog from '../../components/ConfirmationDialog';
import AdminLayout from '../../components/Layout/AdminLayout';
import AppointmentList from '../../components/AppointmentList/AppointmentList';

// QuickActions component
const QuickActions = ({ children }) => (
  <Paper sx={{ p: 3, mb: 4, borderRadius: 2 }}>
    <Typography variant="h6" gutterBottom>Quick Actions</Typography>
    {children}
  </Paper>
);

// SectionTitle component
const SectionTitle = ({ children }) => (
  <Typography variant="h6" sx={{ fontWeight: 600 }}>{children}</Typography>
);

function AdminDashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  // State management
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'info'
  });

  const [isFormOpen, setIsFormOpen] = useState(false);
  const [currentAppointment, setCurrentAppointment] = useState(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [appointmentToDelete, setAppointmentToDelete] = useState(null);

  // GraphQL Queries
  const { loading: loadingAppointments, refetch: refetchAppointments } = useQuery(
    GET_ALL_APPOINTMENTS, 
    { fetchPolicy: 'network-only' }
  );

  const { loading: loadingContacts, refetch: refetchContacts } = useQuery(
    GET_ALL_CONTACTS, 
    { fetchPolicy: 'network-only' }
  );

  // GraphQL Mutations
  const [createAppointment] = useMutation(CREATE_APPOINTMENT, {
    onCompleted: () => {
      refetchAppointments();
      setSnackbar({
        open: true,
        message: 'Appointment created successfully',
        severity: 'success'
      });
      setIsFormOpen(false);
    },
    onError: (error) => {
      setSnackbar({
        open: true,
        message: `Error creating appointment: ${error.message}`,
        severity: 'error'
      });
    }
  });

  const [updateAppointment] = useMutation(UPDATE_APPOINTMENT, {
    onCompleted: () => {
      refetchAppointments();
      setSnackbar({
        open: true,
        message: 'Appointment updated successfully',
        severity: 'success'
      });
      setIsFormOpen(false);
    },
    onError: (error) => {
      setSnackbar({
        open: true,
        message: `Error updating appointment: ${error.message}`,
        severity: 'error'
      });
    }
  });

  const [deleteAppointment] = useMutation(DELETE_APPOINTMENT, {
    onCompleted: () => {
      refetchAppointments();
      setSnackbar({
        open: true,
        message: 'Appointment deleted successfully',
        severity: 'success'
      });
      setDeleteDialogOpen(false);
    },
    onError: (error) => {
      setSnackbar({
        open: true,
        message: `Error deleting appointment: ${error.message}`,
        severity: 'error'
      });
    }
  });

  // Handlers
  const handleOpenForm = (appointment = null) => {
    setCurrentAppointment(appointment);
    setIsFormOpen(true);
  };

  const handleCloseForm = () => {
    setIsFormOpen(false);
    setCurrentAppointment(null);
  };

  const handleSaveAppointment = async (appointmentData) => {
    try {
      const input = {
        ...appointmentData,
        id: appointmentData.id || undefined,
        appointmentDate: appointmentData.appointmentDate.toISOString(),
        status: appointmentData.status?.toUpperCase() || 'PENDING'
      };

      if (appointmentData.id) {
        await updateAppointment({ variables: { input } });
      } else {
        await createAppointment({ variables: { input } });
      }
    } catch (error) {
      console.error('Error saving appointment:', error);
    }
  };

  const handleDeleteAppointment = async () => {
    if (appointmentToDelete) {
      try {
        await deleteAppointment({
          variables: { input: { id: appointmentToDelete.id } }
        });
      } catch (error) {
        console.error('Error deleting appointment:', error);
      }
    }
  };

  const handleCloseSnackbar = (event, reason) => {
    if (reason === 'clickaway') {
      return;
    }
    setSnackbar(prev => ({ ...prev, open: false }));
  };

  return (
    <AdminLayout>
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
      >
        <Alert 
          onClose={handleCloseSnackbar} 
          severity={snackbar.severity}
          sx={{ width: '100%', maxWidth: '100%' }}
          variant="filled"
        >
          {snackbar.message}
          {snackbar.severity === 'success' && (
            <Box sx={{ mt: 2 }}>
              <Button
                variant="contained"
                color="primary"
                startIcon={<AddIcon />}
                onClick={() => handleOpenForm()}
                size={isMobile ? 'small' : 'medium'}
              >
                New Appointment
              </Button>
            </Box>
          )}
        </Alert>
      </Snackbar>

      <Box sx={{ width: '100%', maxWidth: '100%', overflow: 'hidden' }}>
        <QuickActions>
          <Grid container spacing={2}>
            {[
              { 
                label: 'Schedule Appointment', 
                icon: <AddIcon />, 
                path: '/admin/appointments',
                onClick: () => navigate('/admin/appointments')
              },
              { 
                label: 'View Calendar', 
                icon: <CalendarIcon />, 
                path: '/admin/appointments',
                onClick: () => navigate('/admin/appointments')
              },
              { 
                label: 'Send Message', 
                icon: <PeopleIcon />, 
                path: '/admin/messages',
                onClick: () => navigate('/admin/messages')
              },
              { 
                label: 'View Reports', 
                icon: <TrendingUpIcon />, 
                path: '/admin/analytics',
                onClick: () => navigate('/admin/analytics')
              },
            ].map((action, index) => (
              <Grid item xs={12} sm={6} md={3} key={index}>
                <Button
                  fullWidth
                  variant="outlined"
                  startIcon={action.icon}
                  onClick={action.onClick}
                  component="button"
                  sx={{
                    p: 2,
                    height: '100%',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    textAlign: 'center',
                    '& .MuiButton-startIcon': {
                      mr: 0,
                      mb: 1,
                    },
                  }}
                >
                  {action.label}
                </Button>
              </Grid>
            ))}
          </Grid>
        </QuickActions>

        {/* Recent Appointments */}
        <Box sx={{ mb: 4 }}>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
            <SectionTitle>Recent Appointments</SectionTitle>
            <Button 
              color="primary" 
              onClick={() => navigate('/admin/appointments')}
              size={isMobile ? 'small' : 'medium'}
            >
              View All
            </Button>
          </Box>
          <Paper sx={{ borderRadius: 2, overflow: 'hidden' }}>
            <AppointmentList 
              limit={5} 
              onEdit={handleOpenForm}
              onDelete={(appointment) => {
                setAppointmentToDelete(appointment);
                setDeleteDialogOpen(true);
              }}
            />
          </Paper>
        </Box>

        {/* Nested Routes */}
        <Outlet />

        {/* Appointment Form Dialog */}
        <AppointmentForm
          open={isFormOpen}
          onClose={handleCloseForm}
          appointment={currentAppointment}
          onSubmit={handleSaveAppointment}
        />

        {/* Delete Confirmation Dialog */}
        <ConfirmationDialog
          open={deleteDialogOpen}
          onClose={() => setDeleteDialogOpen(false)}
          onConfirm={handleDeleteAppointment}
          title="Delete Appointment"
          content="Are you sure you want to delete this appointment? This action cannot be undone."
        />
      </Box>
    </AdminLayout>
  );
}

export default AdminDashboard;
